from datetime import datetime
current_year = datetime.now().year
print('current_year:', current_year)
files = out  # from prior cell: list of file paths
print('num_files:', len(files))
meta = []
for p in files:
    f = apis.file_system.show_file(access_token=file_system_access_token, file_path=p)
    created_at = f.get('created_at')
    meta.append({'path': p, 'created_at': created_at})
print('sample_meta:', meta[0:3])
# categorize

def parse_dt(s):
    if not s:
        return None
    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        return datetime.fromisoformat(s)

cats = {'Petra': [], 'Budapest': [], 'Amsterdam': []}
for item in meta:
    dt = parse_dt(item['created_at'])
    month = dt.month if dt else None
    year = dt.year if dt else None
    if year == current_year and month == 2:
        cats['Petra'].append(item['path'])
    elif year == current_year and month == 3:
        cats['Budapest'].append(item['path'])
    else:
        cats['Amsterdam'].append(item['path'])
print('counts:', {k: len(v) for k,v in cats.items()})
print('Petra_examples:', cats['Petra'][:5])
print('Budapest_examples:', cats['Budapest'][:5])
print('Amsterdam_examples:', cats['Amsterdam'][:5])

